using Microsoft.Extensions.Configuration;

namespace chatai.Core.Config
{
    public class AppSettingConfig
    {
        private readonly IConfiguration? _config;

        public AppSettingConfig(IConfiguration config)
        {
            _config = config;
        }

        private string GetValue(string key, string defaultValue = "")
        {
            return (_config?.GetSection(key).Value ?? defaultValue).Trim();
        }

        private List<T>? GetList<T>(string key)
        {
            return _config?.GetSection(key).Get<List<T>>() ?? new List<T>();
        }

        /// <summary>
        /// api 允許網域
        /// </summary>
        public List<string>? PolicyDomain => GetList<string>("PolicyDomain");

        /// <summary>
        /// ai api url
        /// </summary>
        public string ApiUrl => GetValue("AiSettings:ApiUrl");

        /// <summary>
        /// ai api key
        /// </summary>
        public string ApiKey => GetValue("AiSettings:ApiKey");

        /// <summary>
        /// ai api keys
        /// </summary>
        public List<string>? FlowIds => GetList<string>("AiSettings:FlowIds");

        /// <summary>
        /// Whisper Url
        /// </summary>
        public string WhisperUrl => GetValue("WhisperUrl");

        /// <summary>
        /// Front Url
        /// </summary>
        public string FrontUrl => GetValue("FrontUrl");

        /// <summary>
        /// Sso Url
        /// </summary>
        public string SsoUrl => GetValue("Sso:Url");

        /// <summary>
        /// Base Url
        /// </summary>
        public string BaseUrl => GetValue("BaseUrl");

        /// <summary>
        /// Base Url Path
        /// </summary>
        public string BaseUrlPath => GetValue("BaseUrlPath");

        /// <summary>
        /// Jwt Secret
        /// </summary>
        public string JwtSecret => GetValue("JwtSecret");

        /// <summary>
        /// Admin Users
        /// </summary>
        public List<string>? AdminUsers => GetList<string>("AdminUsers");

        /// <summary>
        /// 總管理者，可在後台設定其他 AdminUsers 帳號的模組存取權限，不受 admin_permission 表限制、永遠擁有全部模組。
        /// </summary>
        public List<string>? SuperAdminUsers => GetList<string>("SuperAdminUsers");

        /// <summary>
        /// Gemini API Key
        /// </summary>
        public string GeminiApiKey => GetValue("GeminiSettings:ApiKey");

        /// <summary>
        /// Gemini 生成模型
        /// </summary>
        public string GeminiModel => GetValue("GeminiSettings:Model", "gemini-flash-latest");

        /// <summary>
        /// Gemini File Search Store 顯示名稱
        /// </summary>
        public string GeminiStoreDisplayName => GetValue("GeminiSettings:StoreDisplayName", "chatai-flow6-rag");

        /// <summary>
        /// OpenAI API Key（flow=7 帶 ?model=openai 時使用）
        /// </summary>
        public string OpenAiApiKey => GetValue("OpenAiSettings:ApiKey");

        /// <summary>
        /// OpenAI 生成模型
        /// </summary>
        public string OpenAiModel => GetValue("OpenAiSettings:Model", "gpt-4o-mini");

        /// <summary>
        /// Claude（Anthropic）API Key（flow=7 帶 ?model=claude 時使用）
        /// </summary>
        public string ClaudeApiKey => GetValue("ClaudeSettings:ApiKey");

        /// <summary>
        /// Claude 生成模型
        /// </summary>
        public string ClaudeModel => GetValue("ClaudeSettings:Model", "claude-sonnet-4-5-20250929");

        /// <summary>
        /// flow=7（學習規劃探索助手）預設 model=gemini 時專用的 Gemini API Key，
        /// 跟 flow=6（GeminiFileSearchService）的 GeminiSettings:ApiKey、
        /// flow=8（ClassroomFaqChatService）的 GeminiSettings:ClassroomFaqApiKey
        /// 是各自分開的三把 key，換其中一把不會互相影響。
        /// </summary>
        public string AdvisingGeminiApiKey => GetValue("GeminiSettings:AdvisingApiKey");

        /// <summary>
        /// flow=8（未來教室設備支援助理）專用的 Gemini API Key，獨立於 flow=6/7 使用的 key。
        /// </summary>
        public string ClassroomFaqGeminiApiKey => GetValue("GeminiSettings:ClassroomFaqApiKey");

        /// <summary>
        /// flow=8（未來教室設備支援助理）IP 白名單，支援萬用字元（例如 "140.112.31.*"）；
        /// 清單為空或未設定時代表不限制來源 IP。
        /// </summary>
        public List<string>? ClassroomFaqIpWhitelist => GetList<string>("ClassroomFaqIpWhitelist");
    }
}

