using chatai.Adapter.Chatai;
using chatai.Core.Config;
using chatai.Core.Helper;
using chatai.Core.Module;
using chatai.Core.Module.Implement;
using chatai.Core.Service;
using LazyProxy.ServiceProvider;
using Microsoft.Extensions.DependencyInjection;
using ntu.Common.Utility.Helper;
using ntu.Sso.Service;
using ntu.Sso.Service.Implement;

namespace chatai.Core
{
    public static class DependencyInjection
    {
        public static void Init(IServiceProvider provider)
        {
            chatai.Adapter.Chatai.DependencyInjection.Init(provider);

            AutoMapperHelper.Configure(provider);
        }

        public static IServiceCollection AddCoreServices(this IServiceCollection services)
        {
            services.AddAutoMapper(typeof(MappingProfile));

            services.AddSingleton<AppSettingConfig, AppSettingConfig>();
            services.AddSingleton<RsaHelper>();

            services.AddLazyScoped<ISaml2Service, Saml2Service>();

            services.AddAdapterChataiServices();

            services.AddLazyScoped<IChataiModule, ChataiModule>();

            // chatai_backend（學生對話）與 chatai_admin（管理端上傳共用文件）共用同一套 Gemini 串接邏輯
            services.AddHttpClient("Gemini", client =>
            {
                client.BaseAddress = new Uri("https://generativelanguage.googleapis.com");
                client.Timeout = TimeSpan.FromSeconds(60 * 5); // 索引大檔案時輪詢可能要等到 5 分鐘
            });

            // flow=7（學習規劃探索助手）帶 ?model=openai / ?model=claude 時改走這兩個供應商
            services.AddHttpClient("OpenAI", client =>
            {
                client.BaseAddress = new Uri("https://api.openai.com");
                client.Timeout = TimeSpan.FromSeconds(60 * 2);
            });
            services.AddHttpClient("Claude", client =>
            {
                client.BaseAddress = new Uri("https://api.anthropic.com");
                client.Timeout = TimeSpan.FromSeconds(60 * 2);
            });

            services.AddSingleton<IGeminiFileSearchService, GeminiFileSearchService>();
            services.AddSingleton<IAdvisingChatService, AdvisingChatService>();
            services.AddSingleton<IClassroomFaqChatService, ClassroomFaqChatService>();

            return services;
        }

    }
}

