520	        private static bool ShouldIncludeResourceList(IReadOnlyList<(string Role, string Text)> history)
521	        {
522	            return history.Any(h => h.Role == "model" && h.Text.Contains("第 10 / 10 題"));
523	        }
524	
525	        private static string BuildSystemInstruction(bool includeResourceList)
526	        {
527	            if (includeResourceList)
528	                return SystemInstructionText;
529	
530	            var start = SystemInstructionText.IndexOf(ResourceListStartMarker, StringComparison.Ordinal);
531	            var end = SystemInstructionText.IndexOf(ResourceListEndMarker, StringComparison.Ordinal);
532	
533	            if (start < 0 || end < 0 || end <= start)
534	                return SystemInstructionText; // marker 對不上時保守回傳完整版，不要漏掉清單
535	
536	            return SystemInstructionText.Remove(start, end - start);
537	        }
538	
539	        public async IAsyncEnumerable<GeminiStreamChunk> QueryStreamAsync(
540	            string question,
541	            IReadOnlyList<(string Role, string Text)> history,
542	            string model = "gemini")
543	        {
544	            var stream = model?.Trim().ToLowerInvariant() switch
545	            {
546	                "openai" => QueryOpenAiStreamAsync(question, history),
547	                "claude" => QueryClaudeStreamAsync(question, history),
548	                _ => QueryGeminiStreamAsync(question, history),
549	            };
550	
551	            await foreach (var chunk in stream)
552	                yield return chunk;
553	        }
554	
555	        private async IAsyncEnumerable<GeminiStreamChunk> QueryGeminiStreamAsync(
556	            string question,
557	            IReadOnlyList<(string Role, string Text)> history)
558	        {
559	            var client = CreateGeminiClient();
560	
561	            var contents = history
562	                .Select(h => new { role = h.Role, parts = new[] { new { text = h.Text } } })
563	                .Append(new { role = "user", parts = new[] { new { text = question } } })
564	                .ToArray();
565	
566	            var systemInstructionText = BuildSystemInstruction(ShouldIncludeResourceList(history));
567	
568	            var requestBody = new
569	            {
570	                contents,
571	                systemInstruction = new { parts = new[] { new { text = systemInstructionText } } },
572	                generationConfig = new { temperature = 0.7 },
573	            };
574	
575	            using var content = new StringContent(JsonSerializer.Serialize(requestBody), Encoding.UTF8, "application/json");
576	            using var request = new HttpRequestMessage(
577	                HttpMethod.Post,
578	                $"/v1beta/models/{_appSetting.GeminiModel}:streamGenerateContent?alt=sse")
579	            {
580	                Content = content,
581	            };
582	
583	            using var resp = await client.SendAsync(request, HttpCompletionOption.ResponseHeadersRead);
584	
585	            if (!resp.IsSuccessStatusCode)
586	            {
587	                var errorBody = await resp.Content.ReadAsStringAsync();
588	                _logger.LogError("Gemini streamGenerateContent (flow 7) failed: {Status} {Body}", resp.StatusCode, errorBody);
589	                yield return new GeminiStreamChunk { Error = $"Gemini API 呼叫失敗 ({(int)resp.StatusCode}): {errorBody}" };
590	                yield break;
591	            }
592	
593	            await using var stream = await resp.Content.ReadAsStreamAsync();
594	            using var reader = new StreamReader(stream, Encoding.UTF8);
595	
596	            string? line;
597	            while ((line = await reader.ReadLineAsync()) != null)
598	            {
599	                if (!line.StartsWith("data: "))
600	                    continue;
601	
602	                using var doc = JsonDocument.Parse(line["data: ".Length..]);
603	
604	                if (!doc.RootElement.TryGetProperty("candidates", out var candidates) || candidates.GetArrayLength() == 0)
605	                    continue;
606	
607	                var candidate = candidates[0];
608	
609	                if (candidate.TryGetProperty("content", out var contentEl) &&
