                if (!IpHelper.IsMatchIpAddress(new[] { clientIp }, ipWhitelist))
                {
                    _logger.LogWarning("flow=8 拒絕來源 IP {ClientIp} 存取。", clientIp);
                    return StatusCode(StatusCodes.Status403Forbidden, "此功能僅開放特定網路環境使用，請洽數位學習中心。");
                }
            }

            var userId = JWTHelper.GetAccountNameFromRequest(Request);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");

            if (!body.TryGetProperty("input_value", out var inputValueEl))
                return BadRequest("Missing input_value.");

            var inputValue = inputValueEl.GetString() ?? "";

            var history = new List<(string Role, string Text)>();
            if (body.TryGetProperty("history", out var historyEl) && historyEl.ValueKind == JsonValueKind.Array)
            {
                foreach (var item in historyEl.EnumerateArray())
                {
                    var role = item.TryGetProperty("role", out var roleEl) ? roleEl.GetString() : null;
                    var text = item.TryGetProperty("text", out var textEl) ? textEl.GetString() : null;
                    if (string.IsNullOrEmpty(role) || string.IsNullOrEmpty(text))
                        continue;
                    history.Add((role, text));
                }
            }

            (string MimeType, string Base64Data)? image = null;
            if (body.TryGetProperty("image", out var imageEl) && imageEl.ValueKind == JsonValueKind.Object)
            {
                var mimeType = imageEl.TryGetProperty("mimeType", out var mimeEl) ? mimeEl.GetString() : null;
                var data = imageEl.TryGetProperty("data", out var dataEl) ? dataEl.GetString() : null;
                if (!string.IsNullOrEmpty(mimeType) && !string.IsNullOrEmpty(data))
                    image = (mimeType, data);
            }

            Response.ContentType = "text/event-stream";
            Response.Headers.Append("Cache-Control", "no-cache");
            Response.Headers.Append("x-flow", $"{ClassroomFaqFlowIndex}");

            await foreach (var chunk in _classroomFaqService.QueryStreamAsync(inputValue, history, image))
            {
                var payload = JsonSerializer.Serialize(new
                {
                    delta = chunk.Delta,
                    source = chunk.Source,
                    done = chunk.Done,
                    error = chunk.Error,
                });
                await Response.WriteAsync($"data: {payload}\n\n");
                await Response.Body.FlushAsync();
            }

            return new EmptyResult();
        }
    }
}

